plugins {
    id 'application'
    id 'java'
}

group = 'com.example.stage'
version = '1.0.0'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(17)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    implementation 'com.badlogicgames.gdx:gdx:1.14.2'
    implementation 'com.badlogicgames.gdx:gdx-backend-headless:1.14.2'
    implementation 'com.badlogicgames.gdx:gdx-platform:1.14.2:natives-desktop'
}

application {
    mainClass = 'com.example.stage.StageSim'
    applicationDefaultJvmArgs = ['-Xms64m', '-Xmx512m']
}

// Make the run task accept --args="..." as documented.
run {
    standardInput = System.in
}

// Force UTF-8 source encoding so our source files always read the same way.
tasks.withType(JavaCompile).configureEach {
    options.encoding = 'UTF-8'
}
tasks.withType(Jar).configureEach {
    manifest {
        attributes 'Main-Class': application.mainClass
    }
}

