/** 2D scene graph node. An actor has a position, rectangular size, origin, scale, rotation, Z index, and color. The position
 * corresponds to the unrotated, unscaled bottom left corner of the actor. The position is relative to the actor's parent. The
 * origin is relative to the position and is used for scale and rotation.
 * 
* An actor has a list of in progress {@link Action actions} that are applied to the actor (often over time). These are generally * used to change the presentation of the actor (moving it, resizing it, etc). See {@link #act(float)}, {@link Action}, and its * many subclasses. *

* An actor has two kinds of listeners associated with it: "capture" and regular. The listeners are notified of events the actor * or its children receive. The regular listeners are designed to allow an actor to respond to events that have been delivered. * The capture listeners are designed to allow a parent or container actor to handle events before child actors. See {@link #fire} * for more details. *

* An {@link InputListener} can receive all the basic input events. More complex listeners (like {@link ClickListener} and * {@link ActorGestureListener}) can listen for and combine primitive events and recognize complex interactions like multi-touch * or pinch. * @author mzechner * @author Nathan Sweet */ public class Actor { static public PoolManager POOLS = new PoolManager(); static { POOLS.addPool(Rectangle.class, Rectangle::new); POOLS.addPool(Array.class, Array::new); POOLS.addPool(GlyphLayout.class, GlyphLayout::new); POOLS.addPool(ChangeEvent.class, ChangeEvent::new); } private @Null Stage stage; @Null Group parent; private final DelayedRemovalArray listeners = new DelayedRemovalArray(0); private final DelayedRemovalArray captureListeners = new DelayedRemovalArray(0); private final Array actions = new Array(0); private @Null String name; private Touchable touchable = Touchable.enabled; private boolean visible = true, debug; float x, y; float width, height; float originX, originY; float scaleX = 1, scaleY = 1; float rotation; final Color color = new Color(1, 1, 1, 1); private @Null Object userObject; /** Draws the actor. The batch is configured to draw in the parent's coordinate system. * {@link Batch#draw(com.badlogic.gdx.graphics.g2d.TextureRegion, float, float, float, float, float, float, float, float, float) * This draw method} is convenient to draw a rotated and scaled TextureRegion. {@link Batch#begin()} has already been called on * the batch. If {@link Batch#end()} is called to draw without the batch then {@link Batch#begin()} must be called before the * method returns. * 
* The default implementation does nothing. * @param parentAlpha The parent alpha, to be multiplied with this actor's alpha, allowing the parent's alpha to affect all * children. */ public void draw (Batch batch, float parentAlpha) { } /** Updates the actor based on time. Typically this is called each frame by {@link Stage#act(float)}. *

* The default implementation calls {@link Action#act(float)} on each action and removes actions that are complete. * @param delta Time in seconds since the last frame. */ public void act (float delta) { Array actions = this.actions; if (actions.size == 0) return; if (stage != null && stage.getActionsRequestRendering()) Gdx.graphics.requestRendering(); try { for (int i = 0; i < actions.size; i++) { Action action = actions.get(i); if (action.act(delta) && i < actions.size) { Action current = actions.get(i); int actionIndex = current == action ? i : actions.indexOf(action, true); if (actionIndex != -1) { actions.removeIndex(actionIndex); action.setActor(null); i--; } } } } catch (RuntimeException ex) { String context = toString(); throw new RuntimeException("Actor: " + context.substring(0, Math.min(context.length(), 128)), ex); } } /** Sets this actor as the event {@link Event#setTarget(Actor) target} and propagates the event to this actor and ascendants as * necessary. If this actor is not in the stage, the stage must be set before calling this method. * 
* Events are fired in 2 phases: *

 * 1.   The first phase (the "capture" phase) notifies listeners on each actor starting at the root and propagating down the * hierarchy to (and including) this actor.
 * 2.   The second phase notifies listeners on each actor starting at this actor and, if {@link Event#getBubbles()} is true, * propagating upward to the root.
 * 
 * If the event is {@link Event#stop() stopped} at any time, it will not propagate to the next actor. * @return true if the event was {@link Event#cancel() cancelled}. */ public boolean fire (Event event) { if (event.getStage() == null) event.setStage(getStage()); event.setTarget(this); // Collect ascendants so event propagation is unaffected by hierarchy changes. Array ascendants = POOLS.obtain(Array.class); Group parent = this.parent; while (parent != null) { ascendants.add(parent); parent = parent.parent; } try { // Notify ascendants' capture listeners, starting at the root. Ascendants may stop an event before children receive it. Object[] ascendantsArray = ascendants.items; for (int i = ascendants.size - 1; i >= 0; i--) { Group currentTarget = (Group)ascendantsArray[i]; currentTarget.notify(event, true); if (event.isStopped()) return event.isCancelled(); } // Notify the target capture listeners. notify(event, true); if (event.isStopped()) return event.isCancelled(); // Notify the target listeners. notify(event, false); if (!event.getBubbles()) return event.isCancelled(); if (event.isStopped()) return event.isCancelled(); // Notify ascendants' actor listeners, starting at the target. Children may stop an event before ascendants receive it. for (int i = 0, n = ascendants.size; i < n; i++) { ((Group)ascendantsArray[i]).notify(event, false); if (event.isStopped()) return event.isCancelled(); } return event.isCancelled(); } finally { ascendants.clear(); POOLS.free(ascendants); } } /** Notifies this actor's listeners of the event. The event is not propagated to any ascendants. The event * {@link Event#setTarget(Actor) target} must be set before calling this method. Before notifying the listeners, this actor is * set as the {@link Event#getListenerActor() listener actor}. If this actor is not in the stage, the stage must be set before * calling this method. * @param capture If true, the capture listeners will be notified instead of the regular listeners. * @return true if the event was {@link Event#cancel() cancelled}. */ public boolean notify (Event event, boolean capture) { if (event.getTarget() == null) throw new IllegalArgumentException("The event target cannot be null."); DelayedRemovalArray listeners = capture ? captureListeners : this.listeners; if (listeners.size == 0) return event.isCancelled(); event.setListenerActor(this); event.setCapture(capture); if (event.getStage() == null) event.setStage(stage); try { listeners.begin(); for (int i = 0, n = listeners.size; i < n; i++) if (listeners.get(i).handle(event)) event.handle(); listeners.end(); } catch (RuntimeException ex) { String context = toString(); throw new RuntimeException("Actor: " + context.substring(0, Math.min(context.length(), 128)), ex); } return event.isCancelled(); } /** Returns the deepest {@link #isVisible() visible} (and optionally, {@link #getTouchable() touchable}) actor that contains * the specified point, or null if no actor was hit. The point is specified in the actor's local coordinate system (0,0 is the * bottom left of the actor and width,height is the upper right). * 
* This method is used to delegate touchDown, mouse, and enter/exit events. If this method returns null, those events will not * occur on this Actor. *

* The default implementation returns this actor if the point is within this actor's bounds and this actor is visible. * @param touchable If true, hit detection will respect the {@link #setTouchable(Touchable) touchability}. * @see Touchable */ public @Null Actor hit (float x, float y, boolean touchable) { if (touchable && this.touchable != Touchable.enabled) return null; if (!isVisible()) return null; return x >= 0 && x < width && y >= 0 && y < height ? this : null; } /** Removes this actor from its parent, if it has a parent. * @see Group#removeActor(Actor) */ public boolean remove () { if (parent != null) return parent.removeActor(this, true); return false; } /** Add a listener to receive events that {@link #hit(float, float, boolean) hit} this actor. See {@link #fire(Event)}. * @see InputListener * @see ClickListener */ public boolean addListener (EventListener listener) { if (listener == null) throw new IllegalArgumentException("listener cannot be null."); if (!listeners.contains(listener, true)) { listeners.add(listener); return true; } return false; } public boolean removeListener (EventListener listener) { if (listener == null) throw new IllegalArgumentException("listener cannot be null."); return listeners.removeValue(listener, true); } public DelayedRemovalArray getListeners () { return listeners; } /** Adds a listener that is only notified during the capture phase. * @see #fire(Event) */ public boolean addCaptureListener (EventListener listener) { if (listener == null) throw new IllegalArgumentException("listener cannot be null."); if (!captureListeners.contains(listener, true)) captureListeners.add(listener); return true; } public boolean removeCaptureListener (EventListener listener) { if (listener == null) throw new IllegalArgumentException("listener cannot be null."); return captureListeners.removeValue(listener, true); } public DelayedRemovalArray getCaptureListeners () { return captureListeners; } public void addAction (Action action) { action.setActor(this); actions.add(action); if (stage != null && stage.getActionsRequestRendering()) Gdx.graphics.requestRendering(); } /** @param action May be null, in which case nothing is done. */ public void removeAction (@Null Action action) { if (action != null && actions.removeValue(action, true)) action.setActor(null); } public Array getActions () { return actions; } /** Returns true if the actor has one or more actions. */ public boolean hasActions () { return actions.size > 0; } /** Removes all actions on this actor. */ public void clearActions () { for (int i = actions.size - 1; i >= 0; i--) actions.get(i).setActor(null); actions.clear(); } /** Removes all listeners on this actor. */ public void clearListeners () { listeners.clear(); captureListeners.clear(); } /** Removes all actions and listeners on this actor. */ public void clear () { clearActions(); clearListeners(); } /** Returns the stage that this actor is currently in, or null if not in a stage. */ public @Null Stage getStage () { return stage; } /** Called by the framework when this actor or any ascendant is added to a group that is in the stage. * @param stage May be null if the actor or any ascendant is no longer in a stage. */ protected void setStage (Stage stage) { this.stage = stage; } /** Returns true if this actor is the same as or is the descendant of the specified actor. */ public boolean isDescendantOf (Actor actor) { if (actor == null) throw new IllegalArgumentException("actor cannot be null."); Actor parent = this; do { if (parent == actor) return true; parent = parent.parent; } while (parent != null); return false; } /** Returns true if this actor is the same as or is the ascendant of the specified actor. */ public boolean isAscendantOf (Actor actor) { if (actor == null) throw new IllegalArgumentException("actor cannot be null."); do { if (actor == this) return true; actor = actor.parent; } while (actor != null); return false; } /** Returns this actor or the first ascendant of this actor that is assignable with the specified type, or null if none were * found. */ public @Null  T firstAscendant (Class type) { if (type == null) throw new IllegalArgumentException("actor cannot be null."); Actor actor = this; do { if (ClassReflection.isInstance(type, actor)) return (T)actor; actor = actor.parent; } while (actor != null); return null; } /** Returns true if the actor's parent is not null. */ public boolean hasParent () { return parent != null; } /** Returns the parent actor, or null if not in a group. */ public @Null Group getParent () { return parent; } /** Called by the framework when an actor is added to or removed from a group. * @param parent May be null if the actor has been removed from the parent. */ protected void setParent (@Null Group parent) { this.parent = parent; } /** Returns true if input events are processed by this actor. */ public boolean isTouchable () { return touchable == Touchable.enabled; } public Touchable getTouchable () { return touchable; } /** Determines how touch events are distributed to this actor. Default is {@link Touchable#enabled}. */ public void setTouchable (Touchable touchable) { this.touchable = touchable; } public boolean isVisible () { return visible; } /** If false, the actor will not be drawn and will not receive touch events. Default is true. */ public void setVisible (boolean visible) { this.visible = visible; } /** Returns true if this actor and all ascendants are visible. */ public boolean ascendantsVisible () { Actor actor = this; do { if (!actor.isVisible()) return false; actor = actor.parent; } while (actor != null); return true; } /** @deprecated Use {@link #ascendantsVisible()}. */ @Deprecated public boolean ancestorsVisible () { return ascendantsVisible(); } /** Returns true if this actor is the {@link Stage#getKeyboardFocus() keyboard focus} actor. */ public boolean hasKeyboardFocus () { Stage stage = getStage(); return stage != null && stage.getKeyboardFocus() == this; } /** Returns true if this actor is t